from __future__ import annotations
import cmath, math
from typing import List, Tuple

Mat = Tuple[Tuple[complex, complex], Tuple[complex, complex]]

def mat(a: complex, b: complex, c: complex, d: complex) -> Mat:
    return ((a, b), (c, d))

def identity() -> Mat:
    return mat(1.0, 0.0, 0.0, 1.0)

def matmul(x: Mat, y: Mat) -> Mat:
    return mat(
        x[0][0]*y[0][0] + x[0][1]*y[1][0], x[0][0]*y[0][1] + x[0][1]*y[1][1],
        x[1][0]*y[0][0] + x[1][1]*y[1][0], x[1][0]*y[0][1] + x[1][1]*y[1][1])

def conj_transpose(x: Mat) -> Mat:
    return mat(x[0][0].conjugate(), x[1][0].conjugate(),
               x[0][1].conjugate(), x[1][1].conjugate())

def fib_F() -> Mat:
    t = 1.0 / ((1.0 + math.sqrt(5.0)) / 2.0)
    s = math.sqrt(t)
    return mat(complex(t), complex(s), complex(s), complex(-t))

def fib_R() -> Mat:
    return mat(cmath.exp(-4j*math.pi/5), 0.0, 0.0, cmath.exp(3j*math.pi/5))

def generators() -> Tuple[Mat, Mat]:
    f, r = fib_F(), fib_R()
    return r, matmul(matmul(f, r), f)

def compile_word(word: List[int]) -> Mat:
    b1, b2 = generators()
    table = {1: b1, -1: conj_transpose(b1), 2: b2, -2: conj_transpose(b2)}
    acc = identity()
    for letter in word:
        acc = matmul(acc, table[letter])
    return acc

if __name__ == "__main__":
    word = [1, 2, 1, 2, -1, -2, 1]
    u = compile_word(word)
    print("rho(word) =", u)
    inv = [-x for x in reversed(word)]
    prod = matmul(u, compile_word(inv))
    err = max(abs(prod[i][j] - identity()[i][j]) for i in range(2) for j in range(2))
    print("word . word^-1 = I up to", err)
